for script in ['test_stage7_export_readback.php','test_stage7_flag_off.php']:
 r=subprocess.run(['C:/xampp/php/php.exe','scripts/'+script,'--fixture',str(fixture)],env=env,cwd=root,capture_output=True,text=True,encoding='utf-8',timeout=180);(fixture.parent/(script+'.stdout.log')).write_text(r.stdout,encoding='utf-8');(fixture.parent/(script+'.stderr.log')).write_text(r.stderr,encoding='utf-8');print(r.stdout.strip().splitlines()[-1] if r.stdout.strip() else 'No result');assert r.returncode==0 and not r.stderr,'Readback failed; preserve logs'
